CREATE SCHEMA public;
CREATE FUNCTION public.prism_currency_migration_draft_state_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'pricing_currency_migration_drafts are not deletable' USING ERRCODE = '55000';
END IF;
IF NEW.draft_id IS DISTINCT FROM OLD.draft_id OR NEW.profile_id IS DISTINCT FROM OLD.profile_id OR NEW.migration_operation_id IS DISTINCT FROM OLD.migration_operation_id OR NEW.operation_kind IS DISTINCT FROM OLD.operation_kind OR NEW.target_currency_code IS DISTINCT FROM OLD.target_currency_code OR NEW.target_currency_symbol IS DISTINCT FROM OLD.target_currency_symbol OR NEW.expected_inventory_id IS DISTINCT FROM OLD.expected_inventory_id OR NEW.expected_inventory_hash IS DISTINCT FROM OLD.expected_inventory_hash OR NEW.expected_inventory_generation IS DISTINCT FROM OLD.expected_inventory_generation OR NEW.expected_reporting_currency_epoch IS DISTINCT FROM OLD.expected_reporting_currency_epoch OR NEW.expected_settings_updated_at IS DISTINCT FROM OLD.expected_settings_updated_at OR NEW.expires_at IS DISTINCT FROM OLD.expires_at OR NEW.normalized_header_hash IS DISTINCT FROM OLD.normalized_header_hash OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'pricing currency migration draft identity is immutable' USING ERRCODE = '55000';
END IF;
IF OLD.status = 'uploading' AND NEW.status IN ('uploading', 'sealed', 'expired') THEN IF NEW.status = 'uploading' AND (NEW.draft_hash IS DISTINCT FROM OLD.draft_hash OR NEW.template_count IS DISTINCT FROM OLD.template_count OR NEW.committed_result_operation_id IS DISTINCT FROM OLD.committed_result_operation_id) THEN RAISE EXCEPTION 'uploading draft content cannot be sealed fields' USING ERRCODE = '55000';
END IF;
RETURN NEW;
END IF;
IF OLD.status = 'sealed' AND NEW.status = 'committed' THEN IF OLD.draft_hash IS NULL OR OLD.template_count IS NULL OR NEW.draft_hash IS DISTINCT FROM OLD.draft_hash OR NEW.template_count IS DISTINCT FROM OLD.template_count OR NEW.received_chunk_count IS DISTINCT FROM OLD.received_chunk_count OR NEW.committed_result_operation_id IS NULL THEN RAISE EXCEPTION 'sealed draft commit transition is invalid' USING ERRCODE = '55000';
END IF;
RETURN NEW;
END IF;
IF NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.received_chunk_count IS NOT DISTINCT FROM OLD.received_chunk_count AND NEW.draft_hash IS NOT DISTINCT FROM OLD.draft_hash AND NEW.template_count IS NOT DISTINCT FROM OLD.template_count AND NEW.committed_result_operation_id IS NOT DISTINCT FROM OLD.committed_result_operation_id AND NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN RETURN NEW;
END IF;
RAISE EXCEPTION 'invalid pricing currency migration draft transition % -> %', OLD.status, NEW.status USING ERRCODE = '55000';
END;
$$;
CREATE FUNCTION public.prism_guard_audit_tombstone_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'audit_retention_tombstones are append-only' USING ERRCODE = '42501';
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_guard_late_audit_artifact() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.ingress_request_id IS NOT NULL AND EXISTS ( SELECT 1 FROM public.audit_retention_tombstones AS t WHERE t.profile_id = NEW.profile_id AND t.ingress_request_id = NEW.ingress_request_id AND COALESCE(NEW.audit_component_created_at, NEW.created_at) < t.cutoff ) THEN NEW.payload := '{}'::jsonb;
NEW.lifecycle_state := 'telemetry_orphaned';
NEW.capture_status := 'tombstoned';
NEW.observed_bytes := 0;
NEW.stored_bytes := 0;
NEW.truncated := false;
NEW.last_safe_error_code := 'audit_retention_tombstoned';
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_guard_late_audit_log() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.ingress_request_id IS NOT NULL AND EXISTS ( SELECT 1 FROM public.audit_retention_tombstones AS t WHERE t.profile_id = NEW.profile_id AND t.ingress_request_id = NEW.ingress_request_id AND NEW.created_at < t.cutoff ) THEN RETURN NULL;
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_guard_late_audit_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.schema_version = 2 AND NEW.ingress_request_id IS NOT NULL AND EXISTS ( SELECT 1 FROM public.audit_retention_tombstones AS t WHERE t.profile_id = NEW.profile_id AND t.ingress_request_id = NEW.ingress_request_id AND NEW.created_at < t.cutoff ) THEN NEW.audit_extension_payload := NULL;
NEW.extension_state := 'omitted';
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_guard_late_audit_staging() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.ingress_request_id IS NOT NULL AND EXISTS ( SELECT 1 FROM public.audit_retention_tombstones AS t WHERE t.profile_id = NEW.profile_id AND t.ingress_request_id = NEW.ingress_request_id AND NEW.created_at < t.cutoff ) THEN NEW.payload := '{}'::jsonb;
NEW.state := 'tombstoned';
NEW.last_safe_error_code := 'audit_retention_tombstoned';
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_guard_log_retention_job() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE min_generation bigint;
drain_claim_allowed boolean;
BEGIN SELECT minimum_worker_generation, legacy_claim_authorized AND legacy_delete_authorized INTO min_generation, drain_claim_allowed FROM public.retention_worker_transition_state WHERE id = 1;
IF TG_OP = 'INSERT' THEN IF NEW.worker_generation IS NULL OR NEW.worker_generation < min_generation THEN RAISE EXCEPTION 'prism_retention_worker_fenced: create requires worker_generation >= %', min_generation USING ERRCODE = '42501';
END IF;
RETURN NEW;
END IF;
IF TG_OP = 'DELETE' THEN IF OLD.worker_generation IS NULL OR (OLD.worker_generation < min_generation AND NOT drain_claim_allowed) THEN RAISE EXCEPTION 'prism_retention_worker_fenced: delete requires worker_generation >= %', min_generation USING ERRCODE = '42501';
END IF;
RETURN OLD;
END IF;
IF NEW.worker_generation IS NULL OR NEW.worker_generation < min_generation THEN IF NOT (drain_claim_allowed AND OLD.contract_version = 1 AND NEW.contract_version = 1) THEN RAISE EXCEPTION 'prism_retention_worker_fenced: update requires worker_generation >= %', min_generation USING ERRCODE = '42501';
END IF;
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_mark_retention_coverage_dirty() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE dataset_name text := TG_ARGV[0];
created_at_value timestamp with time zone;
BEGIN IF TG_OP = 'DELETE' THEN created_at_value := OLD.created_at;
ELSE created_at_value := NEW.created_at;
END IF;
INSERT INTO public.retention_coverage_read_models ( dataset, earliest_retained_at, latest_retained_at, precision, complete, freshness, dirty, updated_at ) VALUES ( dataset_name, created_at_value, created_at_value, 'unavailable', false, 'stale', true, now() ) ON CONFLICT (dataset) DO UPDATE SET earliest_retained_at = CASE WHEN TG_OP = 'INSERT' AND (NOT public.retention_coverage_read_models.dirty OR public.retention_coverage_read_models.xmin = pg_current_xact_id()::xid) THEN public.retention_coverage_read_models.earliest_retained_at WHEN EXCLUDED.earliest_retained_at IS NULL THEN public.retention_coverage_read_models.earliest_retained_at WHEN public.retention_coverage_read_models.earliest_retained_at IS NULL THEN EXCLUDED.earliest_retained_at ELSE LEAST(public.retention_coverage_read_models.earliest_retained_at, EXCLUDED.earliest_retained_at) END, latest_retained_at = CASE WHEN TG_OP = 'INSERT' AND (NOT public.retention_coverage_read_models.dirty OR public.retention_coverage_read_models.xmin = pg_current_xact_id()::xid) THEN public.retention_coverage_read_models.latest_retained_at WHEN EXCLUDED.latest_retained_at IS NULL THEN public.retention_coverage_read_models.latest_retained_at WHEN public.retention_coverage_read_models.latest_retained_at IS NULL THEN EXCLUDED.latest_retained_at ELSE GREATEST(public.retention_coverage_read_models.latest_retained_at, EXCLUDED.latest_retained_at) END, complete = public.retention_coverage_read_models.complete, freshness = CASE WHEN TG_OP = 'INSERT' AND (NOT public.retention_coverage_read_models.dirty OR public.retention_coverage_read_models.xmin = pg_current_xact_id()::xid) THEN public.retention_coverage_read_models.freshness ELSE 'stale' END, dirty = true, updated_at = now();
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_add_partition_indexes(parent_name text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE partition_name text;
BEGIN FOR partition_name IN SELECT child.relname FROM pg_inherits inheritance JOIN pg_class parent ON parent.oid = inheritance.inhparent JOIN pg_namespace parent_ns ON parent_ns.oid = parent.relnamespace JOIN pg_class child ON child.oid = inheritance.inhrelid JOIN pg_namespace child_ns ON child_ns.oid = child.relnamespace WHERE parent_ns.nspname = 'public' AND parent.relname = parent_name AND child_ns.nspname = 'public' LOOP EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I USING btree (profile_id, pricing_status, created_at DESC)', partition_name || '_pricing_status_idx', partition_name);
EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I USING btree (profile_id, unpriced_reason, created_at DESC) WHERE pricing_status = ''unpriced''', partition_name || '_unpriced_reason_idx', partition_name);
EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I USING btree (profile_id, reporting_currency_epoch, created_at DESC)', partition_name || '_epoch_idx', partition_name);
END LOOP;
END;
$$;
CREATE FUNCTION public.prism_pricing_bidi_control_code(codepoint integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT codepoint IS NOT NULL AND ( codepoint = 1564 OR codepoint = 8206 OR codepoint = 8207 OR (codepoint >= 8234 AND codepoint <= 8238) OR (codepoint >= 8294 AND codepoint <= 8297) OR (codepoint >= 8298 AND codepoint <= 8303) ) $$;
CREATE FUNCTION public.prism_pricing_char_to_int(char_text text) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT ascii(char_text) $$;
CREATE FUNCTION public.prism_pricing_components_are_canonical(components text[]) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT components IS NOT NULL AND cardinality(components) > 0 AND components = ARRAY( SELECT component FROM unnest(components) AS component WHERE component IN ('input_price','output_price','cached_input_price','cache_creation_price','reasoning_price') ORDER BY array_position(ARRAY['input_price','output_price','cached_input_price','cache_creation_price','reasoning_price'], component) ) AND cardinality(components) = ( SELECT count(DISTINCT component) FROM unnest(components) AS component ) $$;
CREATE FUNCTION public.prism_pricing_control_or_separator_code(codepoint integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT codepoint IS NOT NULL AND ( (codepoint <= 31) OR (codepoint >= 127 AND codepoint <= 159) OR codepoint = 173 OR (codepoint >= 1536 AND codepoint <= 1541) OR codepoint = 1564 OR codepoint = 1757 OR codepoint = 1807 OR (codepoint >= 2192 AND codepoint <= 2193) OR codepoint = 2274 OR codepoint = 6158 OR (codepoint >= 8203 AND codepoint <= 8207) OR (codepoint >= 8234 AND codepoint <= 8238) OR (codepoint >= 8288 AND codepoint <= 8292) OR (codepoint >= 8298 AND codepoint <= 8303) OR codepoint = 65279 OR (codepoint >= 65529 AND codepoint <= 65532) OR codepoint = 69821 OR codepoint = 69837 OR (codepoint >= 78896 AND codepoint <= 78904) OR (codepoint >= 113824 AND codepoint <= 113827) OR (codepoint >= 917760 AND codepoint <= 917999) OR codepoint = 8232 OR codepoint = 8233 ) $$;
CREATE FUNCTION public.prism_pricing_costs_are_canonical_all_or_none(status text, costs bigint[]) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE index integer;
present boolean;
BEGIN IF costs IS NULL OR cardinality(costs) <> 7 THEN RETURN FALSE;
END IF;
present := FALSE;
FOR index IN 1..7 LOOP IF costs[index] IS NOT NULL THEN present := TRUE;
EXIT;
END IF;
END LOOP;
IF status = 'priced' THEN RETURN present AND costs[1] IS NOT NULL AND costs[2] IS NOT NULL AND costs[3] IS NOT NULL AND costs[4] IS NOT NULL AND costs[5] IS NOT NULL AND costs[6] IS NOT NULL AND costs[7] IS NOT NULL;
END IF;
RETURN NOT present;
END;
$$;
CREATE FUNCTION public.prism_pricing_currency_code_canonical(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE trimmed text;
codepoint integer;
index integer;
BEGIN IF value IS NULL THEN RETURN NULL;
END IF;
trimmed := prism_pricing_trim_unicode_whitespace(value);
IF char_length(trimmed) <> 3 THEN RETURN NULL;
END IF;
FOR index IN 1..3 LOOP codepoint := prism_pricing_char_to_int(substr(trimmed, index, 1));
IF codepoint IS NULL OR NOT ((codepoint >= 65 AND codepoint <= 90) OR (codepoint >= 97 AND codepoint <= 122)) THEN RETURN NULL;
END IF;
END LOOP;
RETURN upper(trimmed);
END;
$$;
CREATE FUNCTION public.prism_pricing_currency_symbol_valid(value text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE codepoint integer;
index integer;
count integer;
BEGIN IF value IS NULL OR octet_length(value) > 20 THEN RETURN FALSE;
END IF;
count := char_length(value);
IF count < 1 OR count > 5 THEN RETURN FALSE;
END IF;
IF prism_pricing_trim_unicode_whitespace(value) <> value THEN RETURN FALSE;
END IF;
FOR index IN 1..count LOOP codepoint := prism_pricing_char_to_int(substr(value, index, 1));
IF codepoint IS NULL OR prism_pricing_control_or_separator_code(codepoint) THEN RETURN FALSE;
END IF;
END LOOP;
RETURN TRUE;
END;
$$;
CREATE FUNCTION public.prism_pricing_epochs_mutable_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'reporting_currency_epochs are append-only' USING ERRCODE = '55000';
END IF;
IF OLD.profile_id IS DISTINCT FROM NEW.profile_id OR OLD.epoch IS DISTINCT FROM NEW.epoch OR OLD.currency_code IS DISTINCT FROM NEW.currency_code OR OLD.effective_at IS DISTINCT FROM NEW.effective_at OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN RAISE EXCEPTION 'reporting_currency_epochs identity fields are immutable' USING ERRCODE = '55000';
END IF;
IF OLD.superseded_at IS NOT NULL AND NEW.superseded_at IS DISTINCT FROM OLD.superseded_at THEN RAISE EXCEPTION 'reporting_currency_epochs superseded_at is immutable once set' USING ERRCODE = '55000';
END IF;
IF NEW.superseded_at IS NOT NULL AND OLD.superseded_at IS NULL THEN IF NEW.updated_at = OLD.updated_at THEN NEW.updated_at := clock_timestamp();
END IF;
RETURN NEW;
END IF;
IF OLD.currency_symbol IS DISTINCT FROM NEW.currency_symbol OR OLD.updated_at IS DISTINCT FROM NEW.updated_at THEN IF OLD.superseded_at IS NULL THEN RETURN NEW;
END IF;
END IF;
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_pricing_exact_decimal_canonical(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $_$ DECLARE integral text;
fractional text;
result text;
BEGIN IF value IS NULL OR length(value) < 1 OR length(value) > 20 THEN RETURN NULL;
END IF;
IF value !~ '^[0-9]+(\.[0-9]+)?$' THEN RETURN NULL;
END IF;
IF position('.' in value) = 0 THEN integral := value;
fractional := NULL;
ELSE integral := split_part(value, '.', 1);
fractional := split_part(value, '.', 2);
END IF;
integral := regexp_replace(integral, '^0+(?=[0-9])', '');
IF integral = '' THEN integral := '0';
END IF;
IF fractional IS NOT NULL THEN fractional := regexp_replace(fractional, '0+$', '');
IF fractional = '' THEN fractional := NULL;
END IF;
END IF;
IF fractional IS NULL THEN result := integral;
ELSE result := integral || '.' || fractional;
END IF;
IF length(result) < 1 OR length(result) > 20 THEN RETURN NULL;
END IF;
RETURN result;
END;
$_$;
CREATE FUNCTION public.prism_pricing_inventory_reconciliation() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE row record;
actual_fx_count integer;
actual_assessment_count integer;
actual_dependency_count integer;
actual_template_count integer;
actual_reporting_count integer;
actual_fx_hash text;
actual_template_hash text;
actual_reporting_hash text;
BEGIN FOR row IN SELECT inventory_id, fx_evidence_count, fx_assessment_count, fx_dependency_count, template_evidence_count, reporting_currency_evidence_count, fx_evidence_hash_root, template_evidence_hash_root, reporting_currency_evidence_hash_root FROM public.pricing_migration_inventories LOOP SELECT count(*), md5(string_agg(row_hash, '' ORDER BY source_fx_row_id)) INTO actual_fx_count, actual_fx_hash FROM public.currency_migration_legacy_fx_evidence WHERE inventory_id = row.inventory_id;
SELECT count(*) INTO actual_assessment_count FROM public.currency_migration_legacy_fx_assessments AS assessments JOIN public.currency_migration_legacy_fx_evidence AS evidence ON evidence.legacy_fx_evidence_id = assessments.legacy_fx_evidence_id WHERE evidence.inventory_id = row.inventory_id;
SELECT count(*) INTO actual_dependency_count FROM public.currency_migration_legacy_fx_dependencies WHERE inventory_id = row.inventory_id;
SELECT count(*), md5(string_agg(row_hash, '' ORDER BY template_id)) INTO actual_template_count, actual_template_hash FROM public.pricing_migration_legacy_template_evidence WHERE inventory_id = row.inventory_id;
SELECT count(*), md5(string_agg(row_hash, '' ORDER BY legacy_reporting_currency_evidence_id)) INTO actual_reporting_count, actual_reporting_hash FROM public.pricing_migration_legacy_reporting_currency_evidence WHERE inventory_id = row.inventory_id;
IF row.fx_evidence_count IS DISTINCT FROM actual_fx_count OR row.fx_assessment_count IS DISTINCT FROM actual_assessment_count OR row.fx_dependency_count IS DISTINCT FROM actual_dependency_count OR row.template_evidence_count IS DISTINCT FROM actual_template_count OR row.reporting_currency_evidence_count IS DISTINCT FROM actual_reporting_count OR row.fx_evidence_hash_root IS DISTINCT FROM actual_fx_hash OR row.template_evidence_hash_root IS DISTINCT FROM actual_template_hash OR row.reporting_currency_evidence_hash_root IS DISTINCT FROM actual_reporting_hash THEN RAISE EXCEPTION 'pricing_migration_inventory_reconciliation: inventory % counts/hashes do not match children', row.inventory_id USING ERRCODE = 'P0001';
END IF;
END LOOP;
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_legacy_snapshots_coherent(snapshot_unit text, snapshot_input text, snapshot_output text, snapshot_cache_read text, snapshot_cache_creation text, snapshot_reasoning text, currency_original text, report_currency text, report_symbol text, fx_rate text, fx_source text, config_version integer) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN IF snapshot_unit IS NOT NULL AND snapshot_unit <> 'PER_1M' THEN RETURN FALSE;
END IF;
IF NOT prism_pricing_snapshot_price_canonical(snapshot_input) OR NOT prism_pricing_snapshot_price_canonical(snapshot_output) OR NOT prism_pricing_snapshot_price_canonical(snapshot_cache_read) OR NOT prism_pricing_snapshot_price_canonical(snapshot_cache_creation) OR NOT prism_pricing_snapshot_price_canonical(snapshot_reasoning) THEN RETURN FALSE;
END IF;
IF NOT prism_pricing_snapshot_currency_canonical(currency_original) OR NOT prism_pricing_snapshot_currency_canonical(report_currency) THEN RETURN FALSE;
END IF;
IF report_symbol IS NOT NULL AND NOT prism_pricing_currency_symbol_valid(report_symbol) THEN RETURN FALSE;
END IF;
IF fx_rate IS NOT NULL AND prism_pricing_exact_decimal_canonical(fx_rate) IS NULL THEN RETURN FALSE;
END IF;
IF fx_source IS NOT NULL AND fx_source NOT IN ('ENDPOINT_SPECIFIC','DEFAULT_1_TO_1') THEN RETURN FALSE;
END IF;
IF fx_source = 'DEFAULT_1_TO_1' AND fx_rate IS NOT NULL AND prism_pricing_exact_decimal_canonical(fx_rate) <> '1' THEN RETURN FALSE;
END IF;
IF fx_source = 'ENDPOINT_SPECIFIC' AND fx_rate IS NULL THEN RETURN FALSE;
END IF;
IF fx_source IS NULL AND fx_rate IS NOT NULL THEN RETURN FALSE;
END IF;
IF config_version IS NOT NULL AND config_version < 1 THEN RETURN FALSE;
END IF;
RETURN TRUE;
END;
$$;
CREATE FUNCTION public.prism_pricing_migration_evidence_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% are append-only', TG_TABLE_NAME USING ERRCODE = '55000';
END;
$$;
CREATE FUNCTION public.prism_pricing_revision_child_shape_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM public.prism_pricing_revision_shape_check(NEW.revision_id);
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_revision_epoch_attribution() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE row record;
BEGIN FOR row IN SELECT revisions.id, revisions.template_id, revisions.currency_attribution, revisions.currency_code, revisions.reporting_currency_epoch_id FROM public.pricing_template_revisions AS revisions WHERE revisions.currency_attribution = 'active_epoch' LOOP IF NOT EXISTS ( SELECT 1 FROM public.reporting_currency_epochs AS epochs JOIN public.pricing_templates AS templates ON templates.id = row.template_id WHERE epochs.id = row.reporting_currency_epoch_id AND epochs.profile_id = templates.profile_id AND epochs.currency_code = row.currency_code ) THEN RAISE EXCEPTION 'pricing_revision_epoch_attribution: revision % epoch attribution mismatch', row.id USING ERRCODE = 'P0001';
END IF;
END LOOP;
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_revision_operation_ownership() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE row record;
kind_mapping text;
item_action text;
BEGIN FOR row IN SELECT revisions.id, revisions.template_id, revisions.created_by_kind, revisions.created_by_operation_id FROM public.pricing_template_revisions AS revisions LOOP IF row.created_by_operation_id IS NULL THEN IF row.created_by_kind <> 'legacy_backfill' THEN RAISE EXCEPTION 'pricing_revision_ownership: revision % has no operation but kind %', row.id, row.created_by_kind USING ERRCODE = 'P0001';
END IF;
CONTINUE;
END IF;
kind_mapping := CASE row.created_by_kind WHEN 'manual_create' THEN 'template_create' WHEN 'manual_edit' THEN 'template_update' WHEN 'import' THEN 'template_import' WHEN 'currency_migration' THEN 'currency_cutover' WHEN 'legacy_migration_repair' THEN 'repair_same_currency' ELSE NULL END;
IF kind_mapping IS NULL THEN RAISE EXCEPTION 'pricing_revision_ownership: revision % kind % cannot reference an operation', row.id, row.created_by_kind USING ERRCODE = 'P0001';
END IF;
SELECT result_kind, ( SELECT action FROM public.pricing_mutation_result_items AS items WHERE items.operation_id = operations.operation_id AND items.template_id = row.template_id ORDER BY items.ordinal ASC LIMIT 1 ) INTO kind_mapping, item_action FROM public.pricing_mutation_operations AS operations WHERE operations.operation_id = row.created_by_operation_id;
IF kind_mapping IS NULL THEN RAISE EXCEPTION 'pricing_revision_ownership: revision % references unknown operation %', row.id, row.created_by_operation_id USING ERRCODE = 'P0001';
END IF;
IF item_action IS NULL OR item_action NOT IN ('created','revision_created','metadata_and_revision') THEN RAISE EXCEPTION 'pricing_revision_ownership: operation % has no revision-creating result item for template %', row.created_by_operation_id, row.template_id USING ERRCODE = 'P0001';
END IF;
IF NOT EXISTS ( SELECT 1 FROM public.pricing_templates AS templates JOIN public.pricing_mutation_operations AS operations ON operations.operation_id = row.created_by_operation_id WHERE templates.id = row.template_id AND operations.profile_id = templates.profile_id ) THEN RAISE EXCEPTION 'pricing_revision_ownership: operation profile mismatch for revision %', row.id USING ERRCODE = 'P0001';
END IF;
END LOOP;
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_revision_shape_check(target_revision_id bigint) RETURNS void LANGUAGE plpgsql AS $$ DECLARE revision_kind text;
threshold integer;
timezone_name text;
expected_digest text;
actual_digest text;
card_count integer;
window_count integer;
actual_roles text[];
expected_roles text[];
specialty_shape_count integer;
BEGIN SELECT template_kind, tier_input_tokens_above, pricing_schedule_timezone, pricing_schedule_digest INTO revision_kind, threshold, timezone_name, expected_digest FROM public.pricing_template_revisions WHERE id = target_revision_id;
IF NOT FOUND THEN RAISE EXCEPTION 'pricing template shape guard: revision % does not exist', target_revision_id USING ERRCODE = 'P0001';
END IF;
SELECT count(*), array_agg(card_role ORDER BY card_role) INTO card_count, actual_roles FROM public.pricing_template_cards WHERE revision_id = target_revision_id;
expected_roles := CASE revision_kind WHEN 'standard' THEN ARRAY['standard']::text[] WHEN 'tiered' THEN ARRAY['tier_above', 'tier_base']::text[] WHEN 'peak_valley' THEN ARRAY['offpeak', 'peak']::text[] ELSE ARRAY[]::text[] END;
IF actual_roles IS DISTINCT FROM expected_roles THEN RAISE EXCEPTION 'pricing template shape guard: revision % kind % requires roles %, got %', target_revision_id, revision_kind, expected_roles, actual_roles USING ERRCODE = 'P0001';
END IF;
SELECT count(DISTINCT format('%s:%s:%s', CASE WHEN cached_input_price IS NULL THEN '1' ELSE '0' END, CASE WHEN cache_creation_price IS NULL THEN '1' ELSE '0' END, CASE WHEN reasoning_price IS NULL THEN '1' ELSE '0' END)) INTO specialty_shape_count FROM public.pricing_template_cards WHERE revision_id = target_revision_id;
IF specialty_shape_count <> 1 THEN RAISE EXCEPTION 'pricing template shape guard: revision % cards have mismatched specialty NULL shape', target_revision_id USING ERRCODE = 'P0001';
END IF;
SELECT count(*) INTO window_count FROM public.pricing_template_windows WHERE revision_id = target_revision_id;
IF revision_kind = 'peak_valley' THEN IF window_count < 1 OR window_count > 32 THEN RAISE EXCEPTION 'pricing template shape guard: peak_valley revision % requires 1..32 windows, got %', target_revision_id, window_count USING ERRCODE = 'P0001';
END IF;
actual_digest := public.prism_pricing_template_windows_digest(target_revision_id);
IF expected_digest IS NULL OR actual_digest IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION 'pricing template shape guard: revision % window digest mismatch', target_revision_id USING ERRCODE = 'P0001';
END IF;
ELSE IF window_count <> 0 OR timezone_name IS NOT NULL OR expected_digest IS NOT NULL THEN RAISE EXCEPTION 'pricing template shape guard: non-peak revision % cannot carry schedule data', target_revision_id USING ERRCODE = 'P0001';
END IF;
END IF;
IF revision_kind = 'tiered' AND (threshold IS NULL OR threshold < 1) THEN RAISE EXCEPTION 'pricing template shape guard: tiered revision % has invalid threshold', target_revision_id USING ERRCODE = 'P0001';
END IF;
RETURN;
END;
$$;
CREATE FUNCTION public.prism_pricing_revision_shape_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM public.prism_pricing_revision_shape_check(NEW.id);
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_revisions_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'pricing_template_revisions are append-only' USING ERRCODE = '55000';
END;
$$;
CREATE FUNCTION public.prism_pricing_settings_epoch_coherence() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE row record;
epoch_code text;
epoch_symbol text;
epoch_active boolean;
BEGIN FOR row IN SELECT settings.profile_id, settings.current_reporting_currency_epoch_id, settings.report_currency_code, settings.report_currency_symbol, settings.pricing_migration_state, settings.legacy_migration_issues FROM public.user_settings AS settings LOOP IF row.current_reporting_currency_epoch_id IS NOT NULL THEN SELECT epochs.currency_code, epochs.currency_symbol, epochs.superseded_at IS NULL INTO epoch_code, epoch_symbol, epoch_active FROM public.reporting_currency_epochs AS epochs WHERE epochs.id = row.current_reporting_currency_epoch_id;
IF NOT FOUND OR NOT epoch_active THEN RAISE EXCEPTION 'pricing_settings_epoch_coherence: profile % points at a non-active epoch', row.profile_id USING ERRCODE = 'P0001';
END IF;
IF epoch_code IS DISTINCT FROM row.report_currency_code OR epoch_symbol IS DISTINCT FROM row.report_currency_symbol THEN RAISE EXCEPTION 'pricing_settings_epoch_coherence: profile % settings currency diverges from active epoch', row.profile_id USING ERRCODE = 'P0001';
END IF;
ELSE IF row.report_currency_code IS NOT NULL OR row.report_currency_symbol IS NOT NULL THEN RAISE EXCEPTION 'pricing_settings_epoch_coherence: profile % has canonical currency without an active epoch pointer', row.profile_id USING ERRCODE = 'P0001';
END IF;
IF row.pricing_migration_state = 'ready' THEN RAISE EXCEPTION 'pricing_settings_epoch_coherence: ready profile % has no active epoch', row.profile_id USING ERRCODE = 'P0001';
END IF;
IF NOT (row.legacy_migration_issues @> ARRAY['invalid_reporting_currency_code']::text[] OR row.legacy_migration_issues @> ARRAY['invalid_reporting_currency_symbol']::text[]) THEN RAISE EXCEPTION 'pricing_settings_epoch_coherence: profile % has no epoch and no typed invalid currency evidence', row.profile_id USING ERRCODE = 'P0001';
END IF;
END IF;
END LOOP;
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_snapshot_currency_canonical(value text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT value IS NULL OR prism_pricing_currency_code_canonical(value) = value $$;
CREATE FUNCTION public.prism_pricing_snapshot_price_canonical(value text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT value IS NULL OR prism_pricing_exact_decimal_canonical(value) = value $$;
CREATE FUNCTION public.prism_pricing_template_child_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'pricing template child rows are append-only' USING ERRCODE = '55000';
END;
$$;
CREATE FUNCTION public.prism_pricing_template_name_canonical(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE trimmed text;
codepoint integer;
index integer;
count integer;
BEGIN IF value IS NULL THEN RETURN NULL;
END IF;
trimmed := prism_pricing_trim_unicode_whitespace(value);
count := char_length(trimmed);
IF count < 1 OR count > 128 OR octet_length(trimmed) > 512 THEN RETURN NULL;
END IF;
FOR index IN 1..count LOOP codepoint := prism_pricing_char_to_int(substr(trimmed, index, 1));
IF codepoint IS NULL OR codepoint = 0 OR prism_pricing_control_or_separator_code(codepoint) OR prism_pricing_bidi_control_code(codepoint) THEN RETURN NULL;
END IF;
END LOOP;
RETURN trimmed;
END;
$$;
CREATE FUNCTION public.prism_pricing_template_pointer_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE row record;
expected_id bigint;
BEGIN FOR row IN SELECT templates.id FROM public.pricing_templates AS templates WHERE templates.deleted_at IS NULL LOOP SELECT revisions.id INTO expected_id FROM public.pricing_template_revisions AS revisions WHERE revisions.template_id = row.id ORDER BY revisions.version DESC LIMIT 1;
IF expected_id IS NULL THEN IF EXISTS ( SELECT 1 FROM public.pricing_templates AS templates WHERE templates.id = row.id AND templates.current_revision_id IS NOT NULL ) THEN RAISE EXCEPTION 'pricing_template_pointer_invariant: template % has a current revision pointer but no revisions', row.id USING ERRCODE = 'P0001';
END IF;
ELSE IF NOT EXISTS ( SELECT 1 FROM public.pricing_templates AS templates WHERE templates.id = row.id AND templates.current_revision_id = expected_id ) THEN RAISE EXCEPTION 'pricing_template_pointer_invariant: template % current_revision_id must point at revision % (highest version)', row.id, expected_id USING ERRCODE = 'P0001';
END IF;
END IF;
END LOOP;
RETURN NULL;
END;
$$;
CREATE FUNCTION public.prism_pricing_template_windows_digest(target_revision_id bigint) RETURNS text LANGUAGE sql STABLE AS $$ SELECT encode(digest(convert_to(COALESCE(string_agg( format('%s,%s,%s', normalized.weekday_mask, normalized.start_minute, normalized.end_minute), E'\n' ORDER BY normalized.weekday_mask, normalized.start_minute, normalized.end_minute ), ''), 'UTF8'), 'sha256'), 'hex') FROM ( SELECT DISTINCT weekday_mask, start_minute, end_minute FROM public.pricing_template_windows WHERE revision_id = target_revision_id ) AS normalized;
$$;
CREATE FUNCTION public.prism_pricing_templates_name_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE canonical text;
BEGIN canonical := prism_pricing_template_name_canonical(NEW.name);
IF canonical IS NULL THEN RAISE EXCEPTION 'pricing_template_name_invalid (id=%)', NEW.id USING ERRCODE = '22023';
END IF;
NEW.name := canonical;
NEW.name_identity := convert_to(canonical, 'UTF8');
RETURN NEW;
END;
$$;
CREATE FUNCTION public.prism_pricing_trim_unicode_whitespace(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE head integer;
tail integer;
BEGIN IF value IS NULL THEN RETURN NULL;
END IF;
head := 1;
tail := char_length(value);
WHILE head <= tail AND prism_pricing_unicode_whitespace_code(prism_pricing_char_to_int(substr(value, head, 1))) LOOP head := head + 1;
END LOOP;
WHILE tail >= head AND prism_pricing_unicode_whitespace_code(prism_pricing_char_to_int(substr(value, tail, 1))) LOOP tail := tail - 1;
END LOOP;
IF head > tail THEN RETURN '';
END IF;
RETURN substr(value, head, tail - head + 1);
END;
$$;
CREATE FUNCTION public.prism_pricing_unicode_whitespace_code(codepoint integer) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT codepoint IS NOT NULL AND ( (codepoint >= 9 AND codepoint <= 13) OR codepoint = 32 OR codepoint = 133 OR codepoint = 160 OR codepoint = 5760 OR (codepoint >= 8192 AND codepoint <= 8202) OR codepoint = 8232 OR codepoint = 8233 OR codepoint = 8239 OR codepoint = 8287 OR codepoint = 12288 ) $$;
