_body bytea, response_body bytea, request_body_encoding character varying(16), response_body_encoding character varying(16), request_body_capture_provenance character varying(32), response_body_capture_provenance character varying(32), request_body_capture_end_state character varying(32), response_body_capture_end_state character varying(32), request_body_capture_status character varying(32), response_body_capture_status character varying(32), request_body_capture_limit_reason character varying(24), response_body_capture_limit_reason character varying(24), request_body_truncated boolean DEFAULT false NOT NULL, response_body_truncated boolean DEFAULT false NOT NULL, request_body_bytes_observed bigint, request_body_bytes_stored bigint, response_body_bytes_observed bigint, response_body_bytes_stored bigint, CONSTRAINT ck_audit_logs_body_capture_limit_reason CHECK ((((request_body_capture_limit_reason IS NULL) OR ((request_body_capture_limit_reason)::text = ANY ((ARRAY['none'::character varying, 'body_cap'::character varying, 'ingress_budget'::character varying, 'both'::character varying, 'handoff_budget'::character varying])::text[]))) AND ((response_body_capture_limit_reason IS NULL) OR ((response_body_capture_limit_reason)::text = ANY ((ARRAY['none'::character varying, 'body_cap'::character varying, 'handoff_budget'::character varying])::text[]))))), CONSTRAINT ck_audit_logs_body_capture_provenance CHECK ((((request_body_capture_provenance IS NULL) OR ((request_body_capture_provenance)::text = ANY ((ARRAY['runtime_bytes'::character varying, 'legacy_text_transcoded'::character varying, 'legacy_unknown'::character varying, 'not_applicable'::character varying])::text[]))) AND ((response_body_capture_provenance IS NULL) OR ((response_body_capture_provenance)::text = ANY ((ARRAY['runtime_bytes'::character varying, 'legacy_text_transcoded'::character varying, 'legacy_unknown'::character varying, 'not_applicable'::character varying])::text[]))))), CONSTRAINT ck_audit_logs_b