aders_scrub_provenance IS NULL) OR ((request_headers_scrub_provenance)::text = ANY ((ARRAY['runtime_scrubbed'::character varying, 'legacy_rescrubbed'::character varying, 'legacy_all_values_redacted'::character varying, 'legacy_unknown'::character varying, 'not_applicable'::character varying])::text[]))) AND ((response_headers_scrub_provenance IS NULL) OR ((response_headers_scrub_provenance)::text = ANY ((ARRAY['runtime_scrubbed'::character varying, 'legacy_rescrubbed'::character varying, 'legacy_all_values_redacted'::character varying, 'legacy_unknown'::character varying, 'not_applicable'::character varying])::text[]))))), CONSTRAINT ck_audit_logs_request_body_capture_end_state CHECK (((request_body_capture_end_state IS NULL) OR ((request_body_capture_end_state)::text = ANY ((ARRAY['complete'::character varying, 'client_disconnected'::character varying, 'read_error'::character varying, 'unknown'::character varying])::text[])))), CONSTRAINT ck_audit_logs_request_body_capture_status CHECK (((request_body_capture_status IS NULL) OR ((request_body_capture_status)::text = ANY ((ARRAY['not_requested'::character varying, 'metadata_only'::character varying, 'pending_body'::character varying, 'captured'::character varying, 'truncated'::character varying, 'omitted_ingress_budget'::character varying, 'omitted_handoff_budget'::character varying, 'materialization_failed'::character varying, 'legacy_unknown'::character varying])::text[])))), CONSTRAINT ck_audit_logs_request_body_closure CHECK (((((request_body_capture_status)::text = ANY ((ARRAY['captured'::character varying, 'truncated'::character varying])::text[])) AND (request_body_bytes_stored > 0) AND (request_body IS NOT NULL)) OR (((request_body_capture_status)::text <> ALL ((ARRAY['captured'::character varying, 'truncated'::character varying])::text[])) AND (request_body IS NULL)))), CONSTRAINT ck_audit_logs_request_body_counts CHECK ((((request_body_bytes_observed IS NULL) AND (request_body_bytes_stored IS NULL)) OR ((r