es_stored <= response_body_bytes_observed)))), CONSTRAINT ck_audit_logs_response_headers_closure CHECK (((((response_headers_capture_status)::text = ANY ((ARRAY['captured'::character varying, 'truncated'::character varying])::text[])) AND (response_headers IS NOT NULL)) OR (((response_headers_capture_status)::text <> ALL ((ARRAY['captured'::character varying, 'truncated'::character varying])::text[])) AND (response_headers IS NULL)))), CONSTRAINT ck_audit_logs_row_kind CHECK (((row_kind)::text = ANY ((ARRAY['planning'::character varying, 'admission'::character varying, 'upstream'::character varying, 'legacy_unknown'::character varying])::text[]))), CONSTRAINT ck_audit_logs_url_scrub_provenance CHECK (((url_scrub_provenance)::text = ANY ((ARRAY['runtime_scrubbed'::character varying, 'legacy_rescrubbed'::character varying, 'legacy_unknown'::character varying, 'not_applicable'::character varying])::text[]))) ) PARTITION BY RANGE (created_at);
